import{_ as a,o as t,c as s,ak as i}from"./chunks/framework.CRPHSmau.js";const u=JSON.parse('{"title":"GitLab Variables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/inheritance/gitlab.md","filePath":"guide/inheritance/gitlab.md","lastUpdated":1789722997000}'),n={name:"guide/inheritance/gitlab.md"};function r(o,e,l,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="gitlab-variables" tabindex="-1">GitLab Variables <a class="header-anchor" href="#gitlab-variables" aria-label="Permalink to “GitLab Variables”">​</a></h1><p>Browse and edit a GitLab group&#39;s or project&#39;s CI/CD variables from <strong>External</strong>. Both GitLab.com and self-managed instances are supported.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><p>Choose <strong>GitLab Variables</strong> when adding an external resource under <strong>Settings → External Resources</strong> (also accessible through <strong>External → Manage</strong>):</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Name             : gitlab-team</span></span>
<span class="line"><span>Variable source  : Group</span></span>
<span class="line"><span>GitLab URL       : https://gitlab.com</span></span>
<span class="line"><span>Group ID or path : my-team/subgroup</span></span>
<span class="line"><span>Access token     : (personal or group access token)</span></span>
<span class="line"><span>Environment scope: *</span></span></code></pre></div><ul><li><strong>GitLab URL</strong> is the instance URL without <code>/api/v4</code>. Include the installation subpath if applicable, for example <code>https://example.com/gitlab</code>.</li><li><strong>Variable source</strong> selects Group or Project. Existing resources continue to use their configured group.</li><li><strong>Group / Project</strong> accepts a numeric ID or the full, unescaped path. For a project, choose Project and enter <code>my-team/my-project</code> or its numeric ID. The API configuration accepts exactly one of <code>group</code> or <code>project</code>.</li><li><strong>Access token</strong> needs <code>api</code> scope, with Owner access for group variables or Maintainer/Owner access for project variables. Personal, group, or project tokens can be used where their permissions allow it. Pika encrypts this token at rest; initialize and unlock the server&#39;s encryption key before saving the resource.</li><li><strong>Environment scope</strong> selects one exact GitLab scope. The default <code>*</code> means variables whose scope is literally <code>*</code>, not every scope. Use a separate resource for <code>production</code>, <code>review/*</code>, or another scope. GitLab&#39;s environment-scope feature availability depends on the instance&#39;s tier.</li><li>The standard outbound proxy options also apply.</li></ul><p>Use <strong>Test connection</strong>, then select the resource to list its variables. Select a key, edit the value, and save. New entries use the variable name as their path, containing letters, digits, or underscores (up to 255 characters). Creating and deleting variables are also supported.</p><p>The viewer shows these settings, and both Edit and New entry let you change them:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td>Masked</td><td>Masks the value in CI job logs. GitLab enforces its masked-value constraints (including at least 8 characters and no spaces or line breaks).</td></tr><tr><td>Protected</td><td>Limits the variable to protected branches and tags.</td></tr><tr><td>Expand variable reference</td><td>Resolves references such as <code>$OTHER_VARIABLE</code>. This is the inverse of GitLab&#39;s <code>raw</code> flag.</td></tr><tr><td>Variable type</td><td>Variable (<code>env_var</code>) or File (<code>file</code>). For File, the value editor holds the file content.</td></tr></tbody></table><p>New entries default to an ordinary, unmasked, unprotected Variable with expansion disabled. Existing entries load their current settings. Value-only API writes still preserve any omitted settings. GitLab validates saves, including any additional masked-value restrictions when expansion is enabled. The existing hidden status is displayed read-only; changing it is not supported.</p><p>Only the configured group&#39;s or project&#39;s own variables are listed. Inherited variables are not included; configure the parent group separately to edit those. Unavailable/hidden values produce a read error rather than appearing as empty editable strings. GitLab does not expose version history through this provider. Variable settings are returned as entry metadata, separate from the value used by inheritance.</p><h2 id="variable-allowlist" tabindex="-1">Variable allowlist <a class="header-anchor" href="#variable-allowlist" aria-label="Permalink to “Variable allowlist”">​</a></h2><p>By default every variable in the configured scope is reachable. Turn on <strong>Enable variable allowlist</strong> to restrict the resource to specific names:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DATABASE_URL</span></span>
<span class="line"><span>/^APP_.*/</span></span></code></pre></div><ul><li>One exact variable name or one <code>/regex/</code> per line; blank lines are ignored.</li><li>Patterns use Go RE2 (no lookahead) and must match the <strong>whole</strong> variable name.</li><li>An enabled but empty list denies every variable — that is the point of the toggle being separate from the text box.</li><li>The check runs before any request leaves pika, so a denied name costs nothing upstream and never appears in listings, search, <strong>Test connection</strong>, or inheritance.</li><li>Invalid patterns are rejected when the resource is saved.</li></ul><h3 id="new-variables-outside-the-allowlist" tabindex="-1">New variables outside the allowlist <a class="header-anchor" href="#new-variables-outside-the-allowlist" aria-label="Permalink to “New variables outside the allowlist”">​</a></h3><p>An allowlist blocks names it doesn&#39;t cover, including names that don&#39;t exist yet — so by default you cannot create one. The <strong>New variables outside the allowlist</strong> setting decides what happens instead:</p><table tabindex="0"><thead><tr><th>Option</th><th>Behaviour</th></tr></thead><tbody><tr><td><strong>Reject them</strong> (default)</td><td>The create is refused. This is the pre-existing behaviour, so upgrading never widens access.</td></tr><tr><td><strong>Create and add to the allowlist</strong></td><td>The variable is created and its exact name is appended to the allowlist, so it stays readable and editable here afterwards. Pika rewrites the resource setting itself.</td></tr><tr><td><strong>Create without adding to the allowlist</strong></td><td>The variable is created but the allowlist is untouched, leaving it write-once and invisible to this resource. Use this to seed a value pika must not read back.</td></tr></tbody></table><p>This only covers brand-new names. A variable that already exists outside the allowlist stays untouchable: reads, updates, and deletes are still refused, and a create attempt that discovers an existing variable is refused too.</p><p>Combine it with the resource&#39;s <a href="./#resource-permissions">permission switches</a> for the common shape of &quot;pika may add variables but never change or read the ones already there&quot;: allowlist on, policy <strong>Create and add</strong>, <em>Change existing entries</em> and <em>Read values</em> off.</p><p>Writes check the exact scope before choosing creation or update. This check and the update are separate GitLab requests, not an atomic transaction. Avoid deleting the same variable concurrently: some GitLab versions have an unscoped fallback when a variable disappears before an update.</p><h2 id="inheritance" tabindex="-1">Inheritance <a class="header-anchor" href="#inheritance" aria-label="Permalink to “Inheritance”">​</a></h2><p>The path is the variable key. Reads return <code>{&quot;value&quot;: &quot;...&quot;}</code>. For a variable containing structured configuration, select its format to decode it before merging:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;resource&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gitlab-team&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;APP_CONFIG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;format&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;yaml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;inject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;settings&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>See <a href="./">Inheritance</a> for the meaning of <code>paths</code>, <code>format</code>, and <code>inject</code>.</p>`,25)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
